"""Tool for submitting a validated source-selection decision."""

from collections.abc import Mapping
from uuid import UUID

from pydantic import ValidationError
from smolagents import Tool

from fin_automation.models.sources import (
    SourceSelection,
)
from fin_automation.tools.tavily_search import (
    TavilySearchTool,
)


def prepare_source_selection_payload(
    payload: object,
) -> object:
    """Remove fields generated by the application.

    Existing identifiers are preserved. Identifiers and timestamps
    belonging to newly created records are removed so Pydantic can
    generate them deterministically.

    Args:
        payload: Source-selection data supplied by the agent.

    Returns:
        Normalized source-selection data.
    """

    if not isinstance(payload, Mapping):
        return payload

    normalized_payload = dict(payload)

    normalized_payload.pop(
        "source_selection_id",
        None,
    )
    normalized_payload.pop(
        "created_at",
        None,
    )

    selections = normalized_payload.get(
        "selections"
    )

    if isinstance(selections, list):
        normalized_selections: list[object] = []

        for selection in selections:
            if not isinstance(selection, Mapping):
                normalized_selections.append(
                    selection
                )
                continue

            normalized_selection = dict(
                selection
            )

            normalized_selection.pop(
                "selection_id",
                None,
            )

            normalized_selections.append(
                normalized_selection
            )

        normalized_payload["selections"] = (
            normalized_selections
        )

    research_requests = normalized_payload.get(
        "additional_research_requests"
    )

    if isinstance(research_requests, list):
        normalized_requests: list[object] = []

        for request in research_requests:
            if not isinstance(request, Mapping):
                normalized_requests.append(
                    request
                )
                continue

            normalized_request = dict(request)

            normalized_request.pop(
                "request_id",
                None,
            )
            normalized_request.pop(
                "created_at",
                None,
            )

            normalized_requests.append(
                normalized_request
            )

        normalized_payload[
            "additional_research_requests"
        ] = normalized_requests

    return normalized_payload


class SubmitSourceSelectionTool(Tool):
    """Validate and store the source-selection decision."""

    name = "submit_source_selection"

    description = """
    Submit the final source-selection decision.

    Call this tool exactly once after reviewing the required Tavily search
    results.

    For every selection, provide:

    - the exact search_result_id returned by tavily_web_search
    - candidate_name or null
    - selected
    - expected_source_category
    - selection_reason
    - exclusion_reason
    - evidence_requirement_ids

    Every selected source must reference at least one exact
    EvidenceRequirement.requirement_id from the ResearchPlan.

    Do not copy title, URL, domain, or raw_content. The application attaches
    those values from the stored SearchResult.

    Do not generate source_selection_id, selection_id, request_id, or
    created_at. The application generates those fields.

    The payload must satisfy the SourceSelection schema.
    """.strip()
    inputs = {
        "payload": {
            "type": "object",
            "description": (
                "The SourceSelection decision containing workflow_id, "
                "plan_id, status, selections, uncovered evidence "
                "requirements, and additional research requests."
            ),
        },
    }

    output_type = "string"

    def __init__(
        self,
        tavily_search_tool: TavilySearchTool,
    ) -> None:
        """Initialize the source-selection submission tool.

        Args:
            tavily_search_tool: Search tool containing the complete
                SearchResult records returned during the current run.
        """

        self._tavily_search_tool = (
            tavily_search_tool
        )
        self._last_selection: (
            SourceSelection | None
        ) = None

        super().__init__()

    @property
    def last_selection(
        self,
    ) -> SourceSelection | None:
        """Return the most recently accepted SourceSelection."""

        return self._last_selection

    def reset(self) -> None:
        """Clear the previously submitted selection."""

        self._last_selection = None

    def _hydrate_source_records(
        self,
        payload: object,
    ) -> object:
        """Attach provider-owned data to selection decisions.

        The agent chooses search_result_id values. Python retrieves the
        corresponding original SearchResult and copies title, URL,
        domain, and raw content into each SelectedSource record.

        Args:
            payload: SourceSelection data supplied by the agent.

        Returns:
            SourceSelection data containing complete source records.

        Raises:
            ValueError: If a search-result identifier is invalid or
                was not returned during the current Tavily operation.
        """

        if not isinstance(payload, Mapping):
            return payload

        hydrated_payload = dict(payload)

        selections = hydrated_payload.get(
            "selections"
        )

        if not isinstance(selections, list):
            return hydrated_payload

        hydrated_selections: list[object] = []

        for selection in selections:
            if not isinstance(selection, Mapping):
                hydrated_selections.append(
                    selection
                )
                continue

            hydrated_selection = dict(
                selection
            )

            raw_result_id = (
                hydrated_selection.get(
                    "search_result_id"
                )
            )

            try:
                search_result_id = UUID(
                    str(raw_result_id)
                )
            except (
                TypeError,
                ValueError,
            ) as error:
                raise ValueError(
                    "A submitted source contains an invalid "
                    "search_result_id."
                ) from error

            search_result = (
                self._tavily_search_tool.get_result(
                    search_result_id
                )
            )

            if search_result is None:
                raise ValueError(
                    "A submitted source references a search result "
                    "that was not returned during the current Tavily "
                    "search."
                )

            hydrated_selection.update(
                {
                    "title": search_result.title,
                    "url": str(search_result.url),
                    "domain": search_result.domain,
                    "raw_content": (
                        search_result.raw_content
                    ),
                }
            )

            hydrated_selections.append(
                hydrated_selection
            )

        hydrated_payload["selections"] = (
            hydrated_selections
        )

        return hydrated_payload

    def forward(
        self,
        payload: dict[str, object],
    ) -> str:
        """Validate and store a source-selection decision.

        Args:
            payload: Source-selection decision created by the agent.

        Returns:
            Confirmation that SourceSelection was accepted.

        Raises:
            ValueError: If the decision violates the application
                contract.
        """

        prepared_payload = (
            prepare_source_selection_payload(
                payload
            )
        )

        hydrated_payload = (
            self._hydrate_source_records(
                prepared_payload
            )
        )

        try:
            source_selection = (
                SourceSelection.model_validate(
                    hydrated_payload
                )
            )
        except ValidationError as error:
            raise ValueError(
                "The submitted source selection does not satisfy "
                f"the SourceSelection contract:\n{error}"
            ) from error

        self._last_selection = (
            source_selection
        )

        selected_count = sum(
            1
            for selection
            in source_selection.selections
            if selection.selected
        )

        return (
            "SourceSelection accepted. "
            f"Status: {source_selection.status.value}. "
            f"Selected sources: {selected_count}."
        )